// kgame/ExpTable.h - the level curve (KExpTable in the 2014 GameServer).
//
// The original read ExpTable.lua at start-up through KExpTable::AddExpTable_LUA and answered two
// questions: how much exp does the next level need, and how much exp has been earned in total at
// level N. Both are answered here from a compiled in table generated by tools/gen_exp_table.py
// from ScriptData/ExpTable.xls (the spreadsheet DBManager exported the .lua from).
#pragma once

#include <cstddef>
#include <cstdint>
#include <vector>

namespace knc::game {

// One row of ExpTable.xls. `expToReach` is the cumulative exp at which the unit holds this level
// (level 2 -> 600, level 3 -> 1300); KExpTable::CheckLevelUp compared the total exp against exactly
// that value. `expToNext` is derived from the following row.
struct ExpEntry {
    int level = 1;
    std::int64_t expToReach = 0;
    std::int64_t expToNext = 0;
};

// Access to the generated array (src/kgame/ExpTableData.gen.cpp).
const ExpEntry* expTableData();
std::size_t expTableSize();

// Level curve queries. The 2014 code had a single global table; the class here keeps the same
// semantics but is testable with a hand built table.
class ExpTable {
public:
    ExpTable();

    int maxLevel() const { return static_cast<int>(entries_.size()); }

    // Level a unit would be at with `exp` total exp (clamped to [1, maxLevel]).
    int levelForExp(std::int64_t exp) const;
    // Cumulative exp required to hold `level` (0 for level 1).
    std::int64_t expToReachLevel(int level) const;
    // Exp the unit must still collect while at `level` to reach the next one; 0 at max level.
    std::int64_t expToNextLevel(int level) const;
    // Exp already collected inside the current level (clamped to [0, expToNextLevel]).
    std::int64_t expWithinLevel(int level, std::int64_t exp) const;

    // Applies `delta` exp and returns the new level plus the leftover exp. Levels above maxLevel
    // keep the excess exp (the original stored it and stopped levelling).
    struct ApplyResult {
        int level = 1;
        std::int64_t exp = 0;
        int levelsGained = 0;
        bool reachedMax = false;
    };
    ApplyResult applyExp(int level, std::int64_t exp, std::int64_t delta) const;

    bool validate() const;

private:
    std::vector<ExpEntry> entries_;  // index = level - 1
};

// Process wide default table (built from the generated data on first use).
const ExpTable& defaultExpTable();

}  // namespace knc::game
